+// Sales from the till: each line is a dish sold, using one recipe portion per
+// qty. Used stock is booked through the ledger with ref `sale:<ticket>`.
+import { dayOf } from "../dates.js";
+import { consume } from "./batches.js";
+import { getDish } from "./menu.js";
+import { getRecipe, scaled } from "./recipes.js";
+import { getItem } from "./items.js";
+
+const round3 = (n) => Math.round(n * 1000) / 1000;
+
+/** True when the ticket was imported before. */
+export function hasTicket(store, ticket) {
+  return (store.data.sales ?? []).some((s) => s.ticket === ticket);
+}
+
+/** Records one sold line and consumes its ingredients; throws not_enough_stock. */
+export function recordSale(store, { ticket, soldAt, dishId, qty }) {
+  const recipe = getRecipe(store, getDish(store, dishId).recipeId);
+  for (const n of scaled(recipe, qty)) consume(store, n.itemId, n.qty, { at: soldAt, ref: `sale:${ticket}` });
+  store.data.sales ??= [];
+  store.data.sales.push({ ticket, soldAt, dishId, qty });
+}
+
+/** Per item: theoretical use (sales) vs actual use (consume movements) from..to, inclusive. */
+export function varianceReport(store, from, to) {
+  const inRange = (instant) => dayOf(instant) >= from && dayOf(instant) <= to;
+  const theoretical = new Map();
+  for (const s of store.data.sales ?? []) {
+    if (!inRange(s.soldAt)) continue;
+    const recipe = getRecipe(store, getDish(store, s.dishId).recipeId);
+    for (const n of scaled(recipe, s.qty)) theoretical.set(n.itemId, (theoretical.get(n.itemId) ?? 0) + n.qty);
+  }
+  const actual = new Map();
+  for (const m of store.data.movements) {
+    if (m.type !== "consume" || !inRange(m.at)) continue;
+    const batch = store.data.batches.find((b) => b.id === m.batchId);
+    if (batch) actual.set(batch.itemId, (actual.get(batch.itemId) ?? 0) + m.qty);
+  }
+  const ids = [...new Set([...theoretical.keys(), ...actual.keys()])].sort((a, b) => a - b);
+  return ids
+    .map((itemId) => {
+      const th = round3(theoretical.get(itemId) ?? 0);
+      const ac = round3(actual.get(itemId) ?? 0);
+      return { itemId, name: getItem(store, itemId).name, theoretical: th, actual: ac, difference: round3(ac - th) };
+    })
+    .filter((l) => l.theoretical > 0 || l.actual > 0);
+}
